"use strict";function query(n){$.ajax({url:_global.root+"annualleave/employee",type:"POST",dataType:"html",data:$(".card-container-base form").serialize(),beforeSend:function(){n||$(".loading-process").fadeIn(300)},success:function(n){$("#div-content").html(n);floatThead("table#data")},error:function(n,t,i){alert(t+": "+i)},complete:function(){n||$(".loading-process").fadeOut(300)}})}function deleteLeaveTrans(n){confirm("Are you sure you want to delete this leave transaction?",function(){$.post(_global.root+"annualleave/Delete",{leaveTransactionId:n},function(n){n.IsSuccessful?query(!1):alert(n.Message)})})}$(document).ready(function(){$("#submit").on("click",function(){query(!1)});query(!0)});